package com.letstudy.backend.controller;
import com.letstudy.backend.model.*; import com.letstudy.backend.repository.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/questions") public class QuestionController {private final QuestionRepository repo;private final TopicRepository topics;public QuestionController(QuestionRepository repo,TopicRepository topics){this.repo=repo;this.topics=topics;}@GetMapping public List<Question> all(){return repo.findAll();}@GetMapping("/topic/{topicId}") public List<Question> byTopic(@PathVariable Long topicId){return repo.findByTopic(topics.findById(topicId).orElseThrow());}@GetMapping("/{id}") public Question one(@PathVariable Long id){return repo.findById(id).orElseThrow();}@PostMapping("/topic/{topicId}") public Question add(@PathVariable Long topicId,@RequestBody Question q){q.setTopic(topics.findById(topicId).orElseThrow());q.setId(null);return repo.save(q);}@PutMapping("/{id}") public Question update(@PathVariable Long id,@RequestBody Question input){Question q=repo.findById(id).orElseThrow();q.setQuestionText(input.getQuestionText());q.setOptionA(input.getOptionA());q.setOptionB(input.getOptionB());q.setOptionC(input.getOptionC());q.setOptionD(input.getOptionD());q.setCorrectAnswer(input.getCorrectAnswer());q.setExplanation(input.getExplanation());if(input.getTopic()!=null&&input.getTopic().getId()!=null)q.setTopic(topics.findById(input.getTopic().getId()).orElseThrow());return repo.save(q);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
